import { Toggle as BaseToggle } from "@base-ui/react/toggle";
import { ToggleGroup as BaseToggleGroup } from "@base-ui/react/toggle-group";
import type { ComponentPropsWithoutRef, ElementType } from "react";
import { cn } from "../../lib/cn";
import "../../styles/toggle.css";

type StaticClass<T extends ElementType> = Omit<ComponentPropsWithoutRef<T>, "className"> & {
  className?: string;
};

export type ToggleVariant = "default" | "outline";
export type ToggleSize = "sm" | "md";

export interface ToggleProps extends StaticClass<typeof BaseToggle> {
  variant?: ToggleVariant;
  size?: ToggleSize;
}

/**
 * A button that stays pressed. Use it for on/off formatting (bold, pinned) and
 * for filters. It exposes aria-pressed to assistive tech.
 */
export function Toggle({ variant = "default", size = "md", className, ...props }: ToggleProps) {
  return (
    <BaseToggle
      className={cn("eui-toggle", `eui-toggle--${variant}`, `eui-toggle--${size}`, className)}
      {...props}
    />
  );
}

export interface ToggleGroupProps extends StaticClass<typeof BaseToggleGroup> {
  /** Lays out the toggles in a joined bar. */
  joined?: boolean;
}

/** A set of toggles where one or many can be pressed. Arrow keys move between them. */
export function ToggleGroup({ joined = true, className, ...props }: ToggleGroupProps) {
  return (
    <BaseToggleGroup
      className={cn("eui-toggle-group", joined && "eui-toggle-group--joined", className)}
      {...props}
    />
  );
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Toggle and ToggleGroup. Pressed state uses the hover surface plus a stronger ring,
   so it reads without relying on color alone. */

.eui-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 36px;
  min-width: 36px;
  padding: 0 10px;
  border: 0;
  border-radius: var(--eui-radius-base);
  background: transparent;
  color: var(--eui-color-fg-muted);
  font-family: inherit;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color var(--eui-duration-fast) var(--eui-easing-out), color var(--eui-duration-fast) var(--eui-easing-out);
}

.eui-toggle--sm {
  height: 32px;
  min-width: 32px;
  font-size: 13px;
}

.eui-toggle--outline {
  box-shadow: inset 0 0 0 var(--eui-border-width) var(--eui-color-border-strong);
  color: var(--eui-color-fg);
}

.eui-toggle:hover:not([data-disabled]) {
  background-color: var(--eui-color-hover);
  color: var(--eui-color-fg);
}

.eui-toggle[aria-pressed="true"] {
  background-color: var(--eui-color-hover);
  color: var(--eui-color-fg);
  box-shadow: inset 0 0 0 var(--eui-border-width) var(--eui-color-fg-muted);
}

.eui-toggle:focus-visible {
  outline: 2px solid var(--eui-color-ring);
  outline-offset: 2px;
}

.eui-toggle[data-disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}

.eui-toggle-group {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 4px;
}

.eui-toggle-group--joined {
  gap: 0;
  padding: 2px;
  border-radius: var(--eui-radius-base);
  background-color: var(--eui-color-surface);
  box-shadow: inset 0 0 0 var(--eui-border-width) var(--eui-color-border);
}

.eui-toggle-group--joined .eui-toggle {
  height: 30px;
}

.eui-toggle-group--joined .eui-toggle[aria-pressed="true"] {
  background-color: var(--eui-color-bg);
  box-shadow: 0 0 0 var(--eui-border-width) var(--eui-color-border), 0 1px 2px rgb(0 0 0 / 0.06);
}
